INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT159-S1-Q16$batch13$, 159, 1, 16, $batch13$Strengthen$batch13$, $batch13$A recent study carefully tracked the specific behaviors of five East African chimpanzee groups of one subspecies, and of two West African groups of another subspecies, in activities such as grooming and foraging. The study found that one of the East African groups was behaviorally more similar to the West African groups than to the other East African groups. It is therefore likely that these behaviors are determined by cultural factors rather than by genetics.$batch13$, $batch13$Which one of the following, if true, provides the most support for the argument?$batch13$, $batch13$A$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Chimpanzees sometimes copy the behavior of other chimpanzees, whether or not they are closely related genetically.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Chimpanzees that are new to a group sometimes bring with them new behaviors as well as new genetic characteristics.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$The chimpanzee groups studied face different environmental challenges due to their different locations in Africa.$batch13$, $batch13$Weakens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$The behavioral differences in the chimpanzee groups studied are sufficient to make each group recognizably distinct from all the others.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$Of the chimpanzee groups studied, the five East African groups live in closer proximity to each other than do the two West African groups.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The chimpanzee behaviors studied are probably determined by culture rather than genetics.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$One East African group behaved more like the two West African groups, a different subspecies, than like the other East African groups of its own subspecies.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$If genes drove the behavior, groups of the same subspecies should behave alike. One group breaks that pattern, so the author points to culture. The argument is stronger if chimps can pick up behaviors from others regardless of relatedness, because that's how culture would spread.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Give a way for behavior to pass between chimps without shared genes.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Chimps copy behavior whether or not they're closely related. That's a mechanism for culture to override subspecies lines.$batch13$), ($batch13$B$batch13$, $batch13$Newcomers bring both behaviors and genes, so this can't separate culture from genetics.$batch13$), ($batch13$C$batch13$, $batch13$Different environments are an alternative explanation for the behavior differences.$batch13$), ($batch13$D$batch13$, $batch13$Each group being distinct doesn't say whether culture or genes made it so.$batch13$), ($batch13$E$batch13$, $batch13$How close the groups live doesn't explain why the odd East African group matches distant West African groups.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT159-S1-Q16$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
